// One tool call from the Honeycrumb agent, plus the shop settings.
const c = $("When Called by Agent").first().json;
const settings = Object.fromEntries($("Read Settings").all().map(i => [i.json.key, i.json.value ?? ""]));
const s = v => String(v ?? "").trim();
return [{
  json: {
    action: s(c.action), phone: s(c.phone).replace(/\D/g, ""), customer_name: s(c.customer_name), turn_id: s(c.turn_id),
    test: c.test === true || s(c.test) === "true",
    query: s(c.query), category: s(c.category).toLowerCase(), sku: s(c.sku), qty: Number(c.qty ?? 1), op: s(c.op).toLowerCase() || "view",
    cake_message: s(c.cake_message), area: s(c.area), fulfilment: s(c.fulfilment).toLowerCase(), address: s(c.address),
    deliver_on: s(c.deliver_on), window: s(c.window), note: s(c.note), email: s(c.email), reason: s(c.reason),
    settings,
  },
}];

// ---- lib-shop.js (included by build.py): prices, carts, zones and delivery rules ----
const SHOP = {
  TZ: "Africa/Lagos",
  OPEN_DAYS: [1, 2, 3, 4, 5, 6], // Monday-Saturday
  CLOSED: ["2026-12-25", "2026-12-26", "2027-01-01"],
  // window label -> start hour
  WINDOWS: {
    delivery: { "10am-1pm": 10, "1pm-4pm": 13, "4pm-6pm": 16 },
    pickup: { "9am-12pm": 9, "12pm-3pm": 12, "3pm-7pm": 15 },
  },
  DAYS_AHEAD: 21,
  MAX_QTY: 50,
  CAKE_MESSAGE_MAX: 30,
  PICKUP: "14 Admiralty Way, Lekki Phase 1, Lagos",
};

const naira = n => "₦" + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const clean = s => String(s ?? "").toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
const parseItems = json => {
  try { const a = JSON.parse(json || "[]"); return Array.isArray(a) ? a : []; } catch (e) { return []; }
};
const subtotalOf = items => items.reduce((s, i) => s + i.qty * i.unit_ngn, 0);
const itemLine = i => i.qty + " × " + i.name + (i.cake_message ? ' (message: "' + i.cake_message + '")' : "") + " = " + naira(i.qty * i.unit_ngn);
const newId = prefix => prefix + Array.from({ length: 4 }, () => "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"[Math.floor(Math.random() * 32)]).join("");

// Product by SKU, else by name words (all words of the query must appear).
function findProduct(products, ref) {
  const r = String(ref ?? "").trim();
  if (!r) return null;
  const bySku = products.find(p => p.sku.toLowerCase() === r.toLowerCase());
  if (bySku) return bySku;
  const words = clean(r).split(" ").filter(w => w.length > 1);
  const hits = products.filter(p => words.every(w => clean(p.name + " " + p.sku).includes(w)));
  return hits.length === 1 ? hits[0] : null;
}

// Delivery zone whose name or alias appears in the customer's text.
function matchZone(zones, text) {
  const t = " " + clean(text) + " ";
  let best = null;
  for (const z of zones) {
    const names = [z.area, ...String(z.aliases ?? "").split(",")].map(clean).filter(Boolean);
    for (const n of names) {
      if (t.includes(" " + n + " ") && (!best || n.length > best.len)) best = { zone: z, len: n.length };
    }
  }
  return best ? best.zone : null;
}

function isOpenDay(d) {
  return SHOP.OPEN_DAYS.includes(d.weekday) && !SHOP.CLOSED.includes(d.toISODate());
}

// Earliest (day, window) that respects the longest lead time in the cart.
function earliestSlot(leadHours, fulfilment, now) {
  const windows = SHOP.WINDOWS[fulfilment] || SHOP.WINDOWS.delivery;
  const ready = now.plus({ hours: leadHours });
  for (let d = now.startOf("day"); d <= now.startOf("day").plus({ days: SHOP.DAYS_AHEAD }); d = d.plus({ days: 1 })) {
    if (!isOpenDay(d)) continue;
    for (const [label, hour] of Object.entries(windows)) {
      if (d.set({ hour }) >= ready) return { date: d, window: label };
    }
  }
  return null;
}

// "Thursday 30 October, 1pm-4pm"
const sayDay = d => d.toFormat("cccc d LLLL");
// ---- end lib-shop.js ----
// Menu lines for the agent: by words and/or category, or a category overview when nothing is asked.
const c = $("Config").first().json;
const products = $input.all().map(i => i.json).filter(p => p.sku);
const line = p => p.name + " [" + p.sku + "]: " + naira(p.price_ngn) + ", serves " + p.serves + ", " +
  (p.lead_hours >= 24 ? p.lead_hours + " hours' notice" : "same day") + ", contains " + p.allergens +
  (p.available ? "" : " (SOLD OUT today)") + ". " + p.description;
const words = clean(c.query).split(" ").filter(w => w.length > 1 && !["the", "and", "for", "you", "have", "any", "do", "of", "a"].includes(w));
let list = products.filter(p => !c.category || p.category === c.category || p.category.startsWith(c.category));
if (words.length) {
  list = list
    .map(p => ({ p, score: words.filter(w => clean([p.name, p.category, p.description, p.allergens, p.sku].join(" ")).includes(w.replace(/s$/, ""))).length }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .map(x => x.p);
}
if (!words.length && !c.category) {
  const cats = [...new Set(products.map(p => p.category))];
  return [{ json: { result: "Menu categories: " + cats.map(cat => {
    const ps = products.filter(p => p.category === cat && p.available);
    return cat + " (" + ps.length + " items, from " + naira(Math.min(...ps.map(p => p.price_ngn))) + ")";
  }).join("; ") + ". Search a category or words for details." } }];
}
if (!list.length) return [{ json: { result: "Nothing on the menu matches \"" + (c.query || c.category) + "\". Categories: " + [...new Set(products.map(p => p.category))].join(", ") + "." } }];
return [{ json: { result: list.slice(0, 8).map(line).join("\n") + "\nEverything is made in a kitchen that also handles nuts, gluten, dairy and eggs." } }];

